export type DeliveryMode = "pickup" | "shipping";

export const enabledDeliveryModes: DeliveryMode[] = ["pickup", "shipping"];

export function deliveryModeLabel(mode: DeliveryMode) {
  if (mode === "pickup") {
    return "Pickup";
  }
  return "Shipping";
}

