import { deliveryModeLabel, enabledDeliveryModes } from "./deliveryModes";

test("default delivery modes", () => {
  expect(enabledDeliveryModes).toEqual(["pickup", "shipping"]);
});

test("delivery labels", () => {
  expect(deliveryModeLabel("pickup")).toBe("Pickup");
  expect(deliveryModeLabel("shipping")).toBe("Shipping");
});
